import React, { useState, useRef, useEffect } from 'react';
import { mockChats, mockMessages, Message, AVATARS, Chat } from '../data/mockData';
import './UserChat.css';

interface UserChatProps {
  onBack: () => void;
}

const UserChat: React.FC<UserChatProps> = ({ onBack }) => {
  const [chats] = useState<Chat[]>(mockChats);
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<Message[]>(mockMessages);
  const [input, setInput] = useState('');
  const [search, setSearch] = useState('');
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const filteredChats = chats.filter(c =>
    c.name.toLowerCase().includes(search.toLowerCase())
  );

  const totalUnread = chats.reduce((a, c) => a + c.unread, 0);

  const handleSend = () => {
    const text = input.trim();
    if (!text || !selectedChat) return;

    const msg: Message = {
      id: Date.now().toString(),
      sender: 'me',
      text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      avatar: AVATARS.me,
    };

    setMessages(prev => [...prev, msg]);
    setInput('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleSelectChat = (chat: Chat) => {
    setSelectedChat(chat);
    setMessages(mockMessages);
  };

  return (
    <div className="user-chat-root">
      {/* Sidebar */}
      <aside className="chat-sidebar">
        <div className="sidebar-header">
          <div className="sidebar-title-row">
            <h2 className="sidebar-title">Chats</h2>
            {totalUnread > 0 && (
              <span className="sidebar-badge">{totalUnread}</span>
            )}
          </div>
          <div className="sidebar-search-wrap">
            <svg className="sidebar-search-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>
            </svg>
            <input
              className="sidebar-search"
              type="text"
              placeholder="Search"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
            <button className="sidebar-mic-btn" aria-label="Voice search">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/>
                <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
                <line x1="12" y1="19" x2="12" y2="23"/>
                <line x1="8" y1="23" x2="16" y2="23"/>
              </svg>
            </button>
          </div>
        </div>

        <div className="chat-list">
          {filteredChats.map(chat => (
            <div
              key={chat.id}
              className={`chat-list-item ${selectedChat?.id === chat.id ? 'chat-list-item--active' : ''}`}
              onClick={() => handleSelectChat(chat)}
            >
              <div className="chat-item-avatar">
                <img src={chat.avatar} alt={chat.name} width="44" height="44" />
                <span className="online-dot" />
              </div>
              <div className="chat-item-info">
                <div className="chat-item-top">
                  <span className="chat-item-name">{chat.name}</span>
                  <span className="chat-item-time">{chat.time}</span>
                </div>
                <span className="chat-item-preview">{chat.lastMessage}</span>
              </div>
              {chat.unread > 0 && (
                <span className="chat-unread">{chat.unread}</span>
              )}
            </div>
          ))}
        </div>
      </aside>

      {/* Main chat area */}
      <main className="chat-main">
        {selectedChat ? (
          <>
            {/* Chat header */}
            <header className="chat-main-header">
              <button className="back-btn mobile-only" onClick={onBack} aria-label="Back">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <polyline points="15 18 9 12 15 6"/>
                </svg>
              </button>
              <div className="chat-main-header-identity">
                <div className="chat-header-avatar-wrap">
                  <img src={selectedChat.avatar} alt={selectedChat.name} width="38" height="38" className="chat-header-avatar" />
                  <span className="online-dot" />
                </div>
                <div>
                  <h3 className="chat-header-name">{selectedChat.name}</h3>
                  <span className="chat-header-status">Active now</span>
                </div>
              </div>
              <div className="chat-header-actions">
                <button className="chat-action-btn" aria-label="Video call">
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <polygon points="23 7 16 12 23 17 23 7"/><rect x="1" y="5" width="15" height="14" rx="2" ry="2"/>
                  </svg>
                </button>
                <button className="chat-action-btn" aria-label="More options">
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <circle cx="12" cy="5" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="19" r="1"/>
                  </svg>
                </button>
              </div>
            </header>

            {/* Messages */}
            <div className="chat-messages-area">
              {messages.map((msg, i) => (
                <div
                  key={msg.id}
                  className={`message-row message-row--${msg.sender}`}
                  style={{ animationDelay: `${i * 0.04}s` }}
                >
                  {msg.sender === 'other' && msg.avatar && (
                    <div className="msg-avatar">
                      <img src={msg.avatar} alt="other" width="34" height="34" />
                    </div>
                  )}
                  <div className={`message-bubble message-bubble--${msg.sender}`}>
                    <p className="message-text">{msg.text}</p>
                    <span className="message-time">{msg.timestamp}</span>
                  </div>
                  {msg.sender === 'me' && msg.avatar && (
                    <div className="msg-avatar">
                      <img src={msg.avatar} alt="me" width="34" height="34" />
                    </div>
                  )}
                </div>
              ))}
              <div ref={bottomRef} />
            </div>

            {/* Input */}
            <div className="chat-input-bar">
              <button className="input-icon-btn" aria-label="Emoji">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/>
                </svg>
              </button>
              <button className="input-icon-btn" aria-label="Attach">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/>
                </svg>
              </button>
              <input
                className="chat-input"
                type="text"
                placeholder="Type a message"
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
              />
              <button
                className={`send-btn ${input.trim() ? 'send-btn--active' : ''}`}
                onClick={handleSend}
                disabled={!input.trim()}
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/>
                </svg>
              </button>
            </div>
          </>
        ) : (
          /* Empty state */
          <div className="chat-empty-state">
            <div className="chat-empty-illustration">
              <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="var(--clr-border)" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>
              </svg>
            </div>
            <h2 className="chat-empty-title">Happy Collaborations</h2>
            <p className="chat-empty-desc">Select a conversation to start messaging</p>

            <button className="back-btn-main" onClick={onBack}>
              ← Back to dashboard
            </button>
          </div>
        )}
      </main>
    </div>
  );
};

export default UserChat;
